use std::process::{Command, Stdio};
use std::time::{Duration, SystemTime, UNIX_EPOCH};

fn help_text(prog: &str) -> String {
    format!("loop 0.6.1\nRich Jones <miserlou@gmail.com>\nUNIX's missing `loop` command\n\nUSAGE:\n    {} [FLAGS] [OPTIONS] [input]...\n\nFLAGS:\n    -D, --error-duration    Exit with timeout error code on duration\n    -h, --help              Prints help information\n    -l, --only-last         Only print the output of the last execution of the command\n    -i, --stdin             Read from standard input\n        --summary           Provide a summary\n    -C, --until-changes     Keep going until the output changes\n    -f, --until-fail        Keep going until the command exit status is non-zero\n    -S, --until-same        Keep going until the output changes\n    -s, --until-success     Keep going until the command exit status is zero\n    -V, --version           Prints version information\n\nOPTIONS:\n    -b, --count-by <count_by>                Amount to increment the counter by [default: 1]\n    -e, --every <every>                      How often to iterate. ex., 5s, 1h1m1s1ms1us [default: 1us]\n        --for <ffor>                         A comma-separated list of values, placed into 4ITEM. ex., red,green,blue\n    -d, --for-duration <for_duration>        Keep going until the duration has elapsed (example 1m30s)\n    -n, --num <num>                          Number of iterations to execute\n    -o, --offset <offset>                    Amount to offset the initial counter by [default: 0]\n    -c, --until-contains <until_contains>    Keep going until the output contains this string\n    -r, --until-error <until_error>          Keep going until the command exit status is the value given\n    -m, --until-match <until_match>          Keep going until the output matches this regular expression\n    -t, --until-time <until_time>            Keep going until a future time, ex. \"2018-04-20 04:20:00\" (Times in UTC.)\n\nARGS:\n    <input>...    The command to be looped\n", prog)
}

fn main() {
    let args_os: Vec<OsString> = env::args_os().collect();
    let prog_raw = args_os.get(0).map(|s| s.to_string_lossy().into_owned()).unwrap_or_else(|| "executable".to_string());
    let prog_base = prog_raw.rsplit('/').next().unwrap_or(&prog_raw).to_string();
    // split -- separator
    let mut dashdash_pos: Option<usize> = None;
    for (idx, a) in args_os.iter().enumerate().skip(1) {
        if a.as_os_str().as_bytes() == b"--" {
            dashdash_pos = Some(idx);
            break;
        }
    }
    let (before_slice, after_slice): (&[OsString], &[OsString]) = match dashdash_pos {
        Some(pos) => (&args_os[1..pos], &args_os[pos+1..]),
        None => (&args_os[1..], &[][..]),
    };
    // state
    let mut flag_error_duration = false;
    let mut flag_help = false;
    let mut flag_only_last = false;
    let mut flag_stdin = false;
    let mut flag_summary = false;
    let mut flag_until_changes = false;
    let mut flag_until_fail = false;
    let mut flag_until_same = false;
    let mut flag_until_success = false;
    let mut flag_version = false;
    let mut opt_count_by: Option<OsString> = None;
    let mut opt_every: Option<OsString> = None;
    let mut opt_for: Option<OsString> = None;
    let mut opt_for_duration: Option<OsString> = None;
    let mut opt_num: Option<OsString> = None;
    let mut opt_offset: Option<OsString> = None;
    let mut opt_until_contains: Option<OsString> = None;
    let mut opt_until_error: Option<OsString> = None;
    let mut opt_until_match: Option<OsString> = None;
    let mut opt_until_time: Option<OsString> = None;
    let mut input_os: Vec<OsString> = Vec::new();
    // for after --, all input
    for a in after_slice {
        input_os.push(a.clone());
    }
    // tracking for duplicate detection: count occurrences
    let mut seen_flags: HashSet<String> = HashSet::new();
    let mut seen_opts: HashSet<String> = HashSet::new();
    // help/version first encountered
    let mut first_help_version: Option<String> = None; // "help" or "version"
    // unknown error immediate
    let mut unknown_error: Option<(String, Option<String>)> = None; // (arg_display, suggestion?)
