fn format_count(offset: f64, count_by: f64, actual: i64, precision: usize) -> String {
    let val = offset + (actual as f64) * count_by;
    if val.is_nan() {
        return "NaN".to_string();
    }
    if val.is_infinite() {
        if val.is_sign_positive() {
            return "inf".to_string();
        } else {
            return "-inf".to_string();
        }
    }
    if precision == 0 {
        format!("{:.0}", val)
    } else {
        format!("{:.*}", precision, val)
    }
