            return Err("timestamp format is invalid".to_string());
        }
    }
    let year: i32 = s[0..4].parse().unwrap();
    let month: u32 = s[5..7].parse().unwrap();
    let day: u32 = s[8..10].parse().unwrap();
    // sep T or space
    if b[10] != b'T' && b[10] != b' ' {
        return Err("timestamp format is invalid".to_string());
    }
    if n < 19 {
        return Err("timestamp format is invalid".to_string());
    }
    if b[13] != b':' || b[16] != b':' {
        return Err("timestamp format is invalid".to_string());
    }
    for &idx in &[11,12,14,15,17,18] {
        if idx >= n || b[idx] < b'0' || b[idx] > b'9' {
            return Err("timestamp format is invalid".to_string());
        }
    }
    let hour: u32 = s[11..13].parse().unwrap();
    let minute: u32 = s[14..16].parse().unwrap();
    let second: u32 = s[17..19].parse().unwrap();
    let mut pos = 19;
    let mut nanos: u32 = 0;
    let mut has_dot = false;
    if pos < n && b[pos] == b'.' {
        has_dot = true;
        pos += 1;
        let frac_start = pos;
        while pos < n && b[pos] >= b'0' && b[pos] <= b'9' {
            pos += 1;
        }
        let frac_str = &s[frac_start..pos];
        if !frac_str.is_empty() {
            // convert to nanos, truncate/pad to 9 digits? For very long frac (e.g., 30 digits), need to handle? Humantime likely truncates to nanos (9 digits) or rounds? Test with long frac "123456789012345" (15 digits) was accepted (no error). How to convert? Probably takes first 9 digits as nanos, ignores rest? Or rounds? Let's assume truncate to 9, pad with zeros if shorter.
            let mut ns_str = frac_str.to_string();
            if ns_str.len() > 9 {
                ns_str.truncate(9);
            } else {
                while ns_str.len() < 9 {
                    ns_str.push('0');
