                    return Err("bad character where digit is expected".to_string());
                }
            } else {
                // any other char after dot/frac (including space, 'Z' lowercase, '+', etc.) => bad character? As observed ".123 " (space) gives bad character, ".123z" (lowercase) gives bad character, ".123+00:00" gives bad character. Good.
                return Err("bad character where digit is expected".to_string());
            }
        }
    } else {
        // no dot
        if pos < n {
            if b[pos] == b'Z' {
                pos += 1;
                if pos != n {
                    return Err("timestamp format is invalid".to_string());
                }
            } else {
                return Err("timestamp format is invalid".to_string());
            }
        }
    }
    // validate ranges
    if month < 1 || month > 12 {
        return Err("numeric component is out of range".to_string());
    }
    let dim = days_in_month(year, month);
    if day < 1 || day > dim {
        return Err("numeric component is out of range".to_string());
    }
    if hour > 23 {
        return Err("numeric component is out of range".to_string());
    }
    if minute > 59 {
        return Err("numeric component is out of range".to_string());
    }
    if second > 60 {
        return Err("numeric component is out of range".to_string());
    }
    // check year <1970 => out of range (before epoch)? As observed 1969, 0001 give out of range. What about 1970 with month/day before epoch? Only 1970-01-01 is epoch, earlier in 1970 impossible (since 1970-01-01 is earliest in 1970). Good. So if year <1970, out of range. What about year 1970 but month/day valid? That's >=epoch, ok.
    if year < 1970 {
        return Err("numeric component is out of range".to_string());
