        return Err("numeric component is out of range".to_string());
    }
    let dur = Duration::new(total_secs as u64, nanos);
    Ok(UNIX_EPOCH + dur)
}

fn count_precision(count_by_str: &str) -> usize {
    if let Some(dot_pos) = count_by_str.find('.') {
        let after = &count_by_str[dot_pos+1..];
        // count digits until 'e'/'E' or end, only digits? For "5." after is "" =>0. For "5.e1" after is "e1" =>0 (since first char 'e' not digit, stop). For "1.00e2" after is "00e2" => count "00" (2) then stop at 'e'. Good.
        let mut cnt = 0;
        for ch in after.chars() {
            if ch >= '0' && ch <= '9' {
                cnt += 1;
            } else if ch == 'e' || ch == 'E' {
                break;
            } else {
                break;
            }
        }
        cnt
    } else {
        0
    }
}

fn format_count(offset: f64, count_by: f64, actual: i64, precision: usize) -> String {
    let val = offset + (actual as f64) * count_by;
    if val.is_nan() {
        return "NaN".to_string();
    }
    if val.is_infinite() {
        if val.is_sign_positive() {
            return "inf".to_string();
        } else {
            return "-inf".to_string();
        }
    }
    if precision == 0 {
        format!("{:.0}", val)
    } else {
        format!("{:.*}", precision, val)
    }
}
